        RETURN CASE p_currency_code
            WHEN 'USD' THEN '$'
            WHEN 'EUR' THEN CHR(8364)
            WHEN 'GBP' THEN CHR(163)
            ELSE p_currency_code || ' '
        END || TO_CHAR(p_amount, 'FM999,999,990.00');
    END format_currency;

