        p_start_date IN DATE,
        p_end_date   IN DATE
    ) RETURN NUMBER IS
        v_count NUMBER := 0;
        v_date  DATE := TRUNC(p_start_date);
    BEGIN
        WHILE v_date <= TRUNC(p_end_date) LOOP
