            RETURN '+1 (' || SUBSTR(v_digits, 2, 3) || ') ' ||
                   SUBSTR(v_digits, 5, 3) || '-' || SUBSTR(v_digits, 8, 4);
        ELSE
            RETURN p_phone;
        END IF;
    END format_phone;

