    ) RETURN DATE;

    FUNCTION get_fiscal_year(
        p_date IN DATE DEFAULT SYSDATE
    ) RETURN NUMBER;

    FUNCTION get_fiscal_quarter(
        p_date IN DATE DEFAULT SYSDATE
    ) RETURN NUMBER;

    -- -----------------------------------------------------------------------
