    -- retry_failed
    -- -----------------------------------------------------------------------
    PROCEDURE retry_failed(
        p_max_retries IN NUMBER DEFAULT 3,
        p_user        IN VARCHAR2 DEFAULT USER
    ) IS
    BEGIN
        UPDATE NOTIFICATION_QUEUE SET
            STATUS = 'PENDING',
            ERROR_MESSAGE = NULL
        WHERE STATUS = 'FAILED'
        AND RETRY_COUNT < p_max_retries;

        COMMIT;
    END retry_failed;

