    ) IS
    BEGIN
        UPDATE NOTIFICATION_QUEUE SET
            STATUS = 'CANCELLED'
        WHERE NOTIFICATION_ID = p_notification_id
        AND STATUS = 'PENDING';
    END cancel_notification;

END PKG_NOTIFICATION;
